window.kbPageData["views/entry/k-7825dc63a27a04ce"] = {"key":"entry/k-7825dc63a27a04ce","state":{"route":"entry/k-7825dc63a27a04ce"},"node":{"id":"k-7825dc63a27a04ce","mode":"k","title":"三角形与梯形面积公式","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":[],"qs":["国考 2024 副省级 行测#71"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"三角形面积等于底乘对应高的一半，梯形面积等于两条平行底边的长度之和乘高的一半。高取垂直距离。","review":{"definition":"三角形面积等于底乘对应高的一半，梯形面积等于两条平行底边的长度之和乘高的一半。高取垂直距离。","explanation":"第71题中，取梯形高为1，角部等腰直角三角形的两条直角边均为2，单块面积为2。设梯形短底为 x，两条斜腰沿45°方向展开，长底两端各比短底多伸出1，所以长底为 x＋2。由梯形与三角形等面积，得 (x＋x＋2)×1÷2＝2，解得短底为1，长底为3。四块三角形的地砖总面积为8。","references":[],"evidence":"且所有三角形和梯形面积均相等。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"国考 2024 副省级 行测#71":{"paper":"国考 2024 副省级 行测","n":71,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",13],"asrc":["a475ecf57d968bc14cd6.pdf",21],"card":"65f7d88efa9d71822a681752","links":[{"id":"k-7825dc63a27a04ce","role":"直接考查","why":"分别以底乘高的一半及上下底之和乘高的一半表示两种面积，再令其相等确定所需线段。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-7825dc63a27a04ce":[["国考 2024 副省级 行测#71"]]}};
